targets.expr:
kube_pod_container_info{namespace="$namespace", pod="$pod"}
* on(pod, container, namespace) group_left(state) (
  label_replace(
    (kube_pod_container_status_running == 1)
    or on(pod, container, namespace) (kube_pod_container_status_waiting == 1)
    or on(pod, container, namespace) (kube_pod_container_status_terminated == 1),
    "state", "$1", "reason", "(.+)"
  )
)

sum by (modelName, gpu, GPU_I_PROFILE, node, GPU_I_ID) (
  gpu:resource:gpu_temp
  * on(UUID, GPU_I_ID)
  group_left(exported_pod, exported_namespace, exported_container, node)
  sgn(
    GPU_POD_UTIL_LIMIT{exported_namespace="$namespace", exported_pod="$pod"}
  )
)
or
sum by (modelName, gpu, GPU_I_PROFILE, node, GPU_I_ID) (
  gpu:resource:gpu_temp
  * on(UUID, GPU_I_ID)
  group_left(exported_pod, exported_namespace, exported_container, node)
  label_replace(
    sgn(
      MIG_POD_ALLOCATED{exported_namespace="$namespace", exported_pod="$pod"}
    ), "node", "$1", "Hostname", "(.+)"
  )
)

