sum by (exported_pod, modelName, gpu, GPU_I_PROFILE, gpu_2) (
    GPU_POD_MEMORY{exported_namespace="$namespace", exported_pod="$pod"}
    * on(exported_namespace, exported_pod) group_left(GPU_I_PROFILE, gpu_2)
    (
        (
            label_replace(
                label_replace(
                    clamp_min(sgn(MIG_POD_ALLOCATED{exported_namespace="$namespace", exported_pod="$pod"}), 0),
                    "UUID", "$1", "MIG_UUID", "(.*)"
                ), "gpu_2", "$1", "gpu", "(.*)"
            )
        )
        or
        (
            label_replace(
                label_replace(
                    clamp_min(sgn(GPU_POD_UTIL_LIMIT{exported_namespace="$namespace", exported_pod="$pod"}), 0),
                    "UUID", "$1", "MIG_UUID", "(.*)"
                ), "gpu_2", "$1", "gpu", "(.*)"
            )
            unless on(exported_pod, exported_namespace)
            MIG_POD_ALLOCATED{exported_namespace="$namespace", exported_pod="$pod"}
        )
    )
)

sum(
  GPU_POD_MEMORY{exported_namespace="$namespace", exported_pod=~"$deployment.*"}
  * on() 
  group_left(GPU_I_PROFILE, gpu_2) 
  label_replace(
    label_replace(
      clamp_min(sgn(MIG_POD_ALLOCATED{exported_namespace="$namespace", exported_pod=~"$deployment.*"}), 0), 
      "UUID", "$1", "MIG_UUID", "(.*)"
    ),
    "gpu_2", "$1", "gpu", "(.*)"
  )
) by (exported_pod, modelName, gpu, GPU_I_PROFILE, gpu_2)

sum by (exported_pod, UUID, gpu, modelName, GPU_I_PROFILE) (
  GPU_POD_MEMORY{
    exported_namespace="$namespace",
    exported_pod="$pod"
  }
  * on(exported_namespace, exported_pod, UUID) group_left(GPU_I_PROFILE)
  (
    sgn(
      GPU_POD_UTIL_LIMIT{
        exported_namespace="$namespace",
        exported_pod="$pod"
      }
    )
    unless
    label_replace(
      sgn(
        MIG_POD_ALLOCATED{
          exported_namespace="$namespace",
          exported_pod="$pod"
        }
      ),
      "UUID", "$1", "MIG_UUID", "(.+)"
    )
    * on (exported_namespace, exported_pod, UUID) group_left()
    sgn(
      GPU_POD_UTIL_LIMIT{
        exported_namespace="$namespace",
        exported_pod="$pod"
      }
    )
  )
)
